-- 087: Hatay, Kilis, Rize ve Siirt kataloglarında kaynaklı turistik kayıtları güçlendir.
WITH seed(name, category, place_type, city, address, latitude, longitude, slug, short_description, long_description, source_url, external_source, verified, trust_score, is_active, content_review_status, tags) AS (VALUES
('Hatay Arkeoloji Müzesi','history','museum','Hatay','Maşuklu Mahallesi, Antakya, Hatay',36.2585,36.1610,'hatay-arkeoloji-muzesi','Hatay ve çevresindeki kazılardan çıkarılan arkeolojik eserleri ve mozaikleri tanıtan müze.','Müze koleksiyonu, Hatay ve çevresindeki antik yerleşimlerde bulunan eserleri kapsar. Ziyaret öncesi güncel açık olma ve erişim bilgisini resmî müze sayfasından kontrol edin.','https://hatay.ktb.gov.tr/TR-60898/muze-ve-orenyerleri.html','curated_seed',true,93,true,'source_backed',jsonb_build_array('arkeoloji','müze','mozaik')),
('Aççana Höyüğü (Alalakh)','history','archaeological_site','Hatay','Varışlı Mahallesi, Reyhanlı, Hatay',36.2680,36.3850,'hatay-accana-hoyugu-alalakh','Amik Ovası’ndaki önemli Tunç Çağı yerleşimlerinden biri olan arkeolojik alan.','Aççana Ören Yeri, antik Alalakh kentiyle ilişkilendirilen ve uzun süreli yerleşim katmanlarıyla bilinen bir arkeolojik alandır. Alanın kazı ve ziyaret koşulları için resmî kaynakları kontrol edin.','https://hatay.ktb.gov.tr/TR-60898/muze-ve-orenyerleri.html','curated_seed',true,91,true,'source_backed',jsonb_build_array('arkeoloji','Tunç Çağı','Amik Ovası')),
('Ravanda Kalesi','history','castle','Kilis','Belenözü çevresi, Kilis',36.8460,36.7480,'kilis-ravanda-kalesi','Kilis’in kuzeybatısında, çevre ovaya hâkim konumda bulunan tarihî kale.','Ravanda Kalesi, stratejik konumu ve farklı dönemlere uzanan tarihî izleriyle Kilis’in öne çıkan kültür mirası alanlarındandır. Ziyaret öncesi ulaşım ve erişim durumunu kontrol edin.','https://kilis.ktb.gov.tr/TR-61661/tarihi-yerler.html','curated_seed',true,92,true,'source_backed',jsonb_build_array('kale','tarih','Belenözü')),
('Alaeddin Yavaşca Müzesi','culture','museum','Kilis','Kilis şehir merkezi',36.7184,37.1212,'kilis-alaeddin-yavasca-muzesi','Kilis doğumlu besteci ve devlet sanatçısı Alaeddin Yavaşca’nın yaşamını ve sanatını tanıtan müze.','Müze, Türk musikisinin önemli isimlerinden Alaeddin Yavaşca’nın yaşamı ve sanat çalışmalarına odaklanır. Güncel ziyaret koşulları için il kültür müdürlüğünün bilgisini kontrol edin.','https://kilis.ktb.gov.tr/TR-383842/kulturel-mirasimiz.html','curated_seed',true,90,true,'source_backed',jsonb_build_array('müze','musiki','kültür')),
('Zilkale','nature','castle','Rize','Çamlıhemşin, Rize',40.9570,40.9580,'rize-zilkale','Fırtına Vadisi’ne hâkim kayalık bir sırt üzerinde yükselen tarihî kale.','Zilkale, Fırtına Vadisi’nin doğal peyzajı içinde yer alan ve Rize’nin en tanınmış tarihî yapılarından biridir. Dağ yolu ve hava koşulları nedeniyle yolculuk öncesi güncel ulaşım durumunu kontrol edin.','https://rize.ktb.gov.tr/','curated_seed',true,92,true,'source_backed',jsonb_build_array('kale','Fırtına Vadisi','Çamlıhemşin')),
('Palovit Şelalesi','nature','waterfall','Rize','Kaçkar Dağları Millî Parkı, Çamlıhemşin, Rize',40.9160,40.9630,'rize-palovit-selalesi','Kaçkar Dağları Millî Parkı içinde, gür su akışıyla bilinen doğal şelale.','Palovit Şelalesi, Rize’nin öne çıkan doğal duraklarındandır. Yağış, yol ve mevsim koşulları erişimi etkileyebileceği için ziyaret öncesinde yerel koşulları kontrol edin.','https://rize.ktb.gov.tr/TR-112780/selaleler.html','curated_seed',true,92,true,'source_backed',jsonb_build_array('şelale','doğa','millî park')),
('Tillo İsmail Fakirullah Türbesi ve Işık Hadisesi Düzeneği','culture','tomb','Siirt','Tillo, Siirt',37.9490,42.0130,'siirt-tillo-ismail-fakirullah-turbesi','İsmail Fakirullah Türbesi ve ışığın belirli günlerde türbeye yansımasını sağlayan tarihî düzenekle tanınır.','Tillo’daki türbe ve ışık hadisesi düzeneği, bölgenin bilim ve inanç tarihiyle ilişkilendirilen önemli kültür mirasıdır. Işık hadisesinin gözlemlenebildiği tarihler için resmî yerel duyurular kontrol edilmelidir.','https://siirt.ktb.gov.tr/','curated_seed',true,91,true,'source_backed',jsonb_build_array('Tillo','türbe','kültür mirası')),
('Rasıl Hacar (Delikli Taş)','nature','viewpoint','Siirt','Botan Vadisi çevresi, Siirt',37.8987,41.9520,'siirt-rasil-hacar-delikli-tas','Botan Vadisi’ne bakan kayalık oluşum ve manzara noktası.','Rasıl Hacar, Botan Vadisi manzarasıyla bilinen doğal seyir noktalarındandır. Kayalık alanlarda güvenli güzergâh dışına çıkılmamalıdır.','https://siirt.ktb.gov.tr/TR-382527/botan-vadisi.html','curated_seed',true,89,true,'source_backed',jsonb_build_array('Botan Vadisi','seyir noktası','doğa'))
)
INSERT INTO public.places(name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,verified,trust_score,is_active,content_review_status,tags)
SELECT s.* FROM seed s
WHERE NOT EXISTS (SELECT 1 FROM public.places p WHERE p.slug=s.slug)
  AND NOT EXISTS (SELECT 1 FROM public.places p WHERE p.city=s.city AND lower(trim(p.name))=lower(trim(s.name)));

UPDATE public.places SET name='St. Pierre Kilisesi', source_url='https://hatay.ktb.gov.tr/TR-60898/muze-ve-orenyerleri.html', short_description='Antakya yakınında, erken Hristiyanlık tarihiyle ilişkilendirilen kaya kilisesi.', verified=true, trust_score=greatest(coalesce(trust_score,0),90), content_review_status='source_backed', updated_at=now()
WHERE city='Hatay' AND slug='osm-node-364696567' AND is_active=true;

